body:
//this function should print all numbers up to NUMBER..

void print_nums()
{
  int i;

  for(i = NUMBER; i < NUMBERl; i++) {
    printf("%d\n",i);
  }

}

On Tue, NUMBER Aug NUMBER, David Neary wrote:

> > Actually the following would be in some way sensible:
> > echo -e "`echo "$enc" | sed 's/%\([NUMBER-NUMBERa-fA-F]\{NUMBER,NUMBER\}\)/\\\x\NUMBER/g'`"
> 
> Why {NUMBER,NUMBER}? Why not {NUMBER}?

no idea.

the above was something along the lines i was attempting, once i 
realised it was a straight swap. but i couldnt get awk's gensub to 
insert the \x for %'s and ='s.

anyway, in the end i found something on the internet and adapted it:

function decode_url (str,    hextab,i,c,cNUMBER,cNUMBER,len,code) {

        # hex to dec lookup table
        hextab ["NUMBER"] = NUMBER;       hextab ["NUMBER"] = NUMBER;
        hextab ["NUMBER"] = NUMBER;       hextab ["NUMBER"] = NUMBER;
        hextab ["NUMBER"] = NUMBER;       hextab ["A"] = NUMBER;
        hextab ["NUMBER"] = NUMBER;       hextab ["B"] = NUMBER;
        hextab ["NUMBER"] = NUMBER;       hextab ["C"] = NUMBER;
        hextab ["NUMBER"] = NUMBER;       hextab ["D"] = NUMBER;
        hextab ["NUMBER"] = NUMBER;       hextab ["E"] = NUMBER;
        hextab ["NUMBER"] = NUMBER;       hextab ["F"] = NUMBER;

        decoded = "";
        i   = NUMBER;
        len = length (str);
        while ( i <= len ) {
                c = substr (str, i, NUMBER);
                # check for usual start of URI hex encoding chars
                if ( c == "%" || c == "=" ) {
                        if ( i+NUMBER <= len ) {
                                # valid hex encoding?
                                cNUMBER = toupper(substr(str, i+NUMBER, NUMBER));
                                cNUMBER = toupper(substr(str, i+NUMBER, NUMBER));
                                if ( !(hextab [cNUMBER] == "" && hextab [cNUMBER] == "") ) {
                                        code = NUMBER + hextab [cNUMBER] * NUMBER + hextab [cNUMBER] + NUMBER
                                        c = sprintf ("%c", code)
                                        i = i + NUMBER
                                }
                        }
                # + is space apparently
                } else if ( c == "+" ) {
                        c = " "
                }
                decoded = decoded c;
                ++i;
        }
        return decoded
}

